{{
  config(
    materialized = 'incremental',
    unique_key = ['queue_id', 'created_date', 'media_type'],
    )
}}
{#- This is only for "voice" queues for the named state queues:
      'ACT', 'NSW', 'Victoria', 'QLD', 'SA', 'Other', 'WA', 'Tasmania', 'NT'
    If you need to add more queues or media types, you will need to
    adjust the WHERE clause accordingly and run a --full-refresh
 -#}
SELECT
    qa.payload:queueId::string AS queue_id,
    q.payload:name::string AS queue_name,
    TO_TIMESTAMP_TZ(SPLIT_PART(qa.payload:interval, '/', 1)::variant)::date AS created_date,
    qa.payload:mediaType::string AS media_type,

    COALESCE(FILTER(qa.payload:metrics, a -> a:metric = 'nBlindTransferred')[0]:stats:count::number, 0) AS nBlindTransferred_count,
    COALESCE(FILTER(qa.payload:metrics, a -> a:metric = 'nBotInteractions')[0]:stats:count::number, 0) AS nBotInteractions_count,
    COALESCE(FILTER(qa.payload:metrics, a -> a:metric = 'nCobrowseSessions')[0]:stats:count::number, 0) AS nCobrowseSessions_count,
    COALESCE(FILTER(qa.payload:metrics, a -> a:metric = 'nConnected')[0]:stats:count::number, 0) AS nConnected_count,
    COALESCE(FILTER(qa.payload:metrics, a -> a:metric = 'nConsult')[0]:stats:count::number, 0) AS nConsult_count,
    COALESCE(FILTER(qa.payload:metrics, a -> a:metric = 'nConsultTransferred')[0]:stats:count::number, 0) AS nConsultTransferred_count,
    COALESCE(FILTER(qa.payload:metrics, a -> a:metric = 'nConversations')[0]:stats:count::number, 0) AS nConversations_count,
    COALESCE(FILTER(qa.payload:metrics, a -> a:metric = 'nError')[0]:stats:count::number, 0) AS nError_count,
    COALESCE(FILTER(qa.payload:metrics, a -> a:metric = 'nOffered')[0]:stats:count::number, 0) AS nOffered_count,
    COALESCE(FILTER(qa.payload:metrics, a -> a:metric = 'nOutbound')[0]:stats:count::number, 0) AS nOutbound_count,
    COALESCE(FILTER(qa.payload:metrics, a -> a:metric = 'nOutboundAbandoned')[0]:stats:count::number, 0) AS nOutboundAbandoned_count,
    COALESCE(FILTER(qa.payload:metrics, a -> a:metric = 'nOutboundAttempted')[0]:stats:count::number, 0) AS nOutboundAttempted_count,
    COALESCE(FILTER(qa.payload:metrics, a -> a:metric = 'nOutboundConnected')[0]:stats:count::number, 0) AS nOutboundConnected_count,
    COALESCE(FILTER(qa.payload:metrics, a -> a:metric = 'nOverSla')[0]:stats:count::number, 0) AS nOverSla_count,
    COALESCE(FILTER(qa.payload:metrics, a -> a:metric = 'nTransferred')[0]:stats:count::number, 0) AS nTransferred_count,

    FILTER(qa.payload:metrics, a -> a:metric = 'oServiceLevel')[0]:stats:denominator::number AS oServiceLevel_denominator,
    FILTER(qa.payload:metrics, a -> a:metric = 'oServiceLevel')[0]:stats:numerator::number AS oServiceLevel_numerator,
    FILTER(qa.payload:metrics, a -> a:metric = 'oServiceLevel')[0]:stats:ratio::number(38,4) AS oServiceLevel_ratio,
    FILTER(qa.payload:metrics, a -> a:metric = 'oServiceLevel')[0]:stats:target::number(38,4) AS oServiceLevel_target,
    FILTER(qa.payload:metrics, a -> a:metric = 'oServiceTarget')[0]:stats:current::number(38,4) AS oServiceTarget_current,

    COALESCE(FILTER(qa.payload:metrics, a -> a:metric = 'tAbandon')[0]:stats:count::number, 0) AS tAbandon_count,
    COALESCE(FILTER(qa.payload:metrics, a -> a:metric = 'tAbandon')[0]:stats:max::number, 0) AS tAbandon_max,
    COALESCE(FILTER(qa.payload:metrics, a -> a:metric = 'tAbandon')[0]:stats:min::number, 0) AS tAbandon_min,
    COALESCE(FILTER(qa.payload:metrics, a -> a:metric = 'tAbandon')[0]:stats:sum::number, 0) AS tAbandon_sum,
    COALESCE(FILTER(qa.payload:metrics, a -> a:metric = 'tAcd')[0]:stats:count::number, 0) AS tAcd_count,
    COALESCE(FILTER(qa.payload:metrics, a -> a:metric = 'tAcd')[0]:stats:max::number, 0) AS tAcd_max,
    COALESCE(FILTER(qa.payload:metrics, a -> a:metric = 'tAcd')[0]:stats:min::number, 0) AS tAcd_min,
    COALESCE(FILTER(qa.payload:metrics, a -> a:metric = 'tAcd')[0]:stats:sum::number, 0) AS tAcd_sum,
    COALESCE(FILTER(qa.payload:metrics, a -> a:metric = 'tActiveCallbackComplete')[0]:stats:count::number, 0) AS tActiveCallbackComplete_count,
    COALESCE(FILTER(qa.payload:metrics, a -> a:metric = 'tActiveCallbackComplete')[0]:stats:max::number, 0) AS tActiveCallbackComplete_max,
    COALESCE(FILTER(qa.payload:metrics, a -> a:metric = 'tActiveCallbackComplete')[0]:stats:min::number, 0) AS tActiveCallbackComplete_min,
    COALESCE(FILTER(qa.payload:metrics, a -> a:metric = 'tActiveCallbackComplete')[0]:stats:sum::number, 0) AS tActiveCallbackComplete_sum,
