    COALESCE(FILTER(qa.payload:metrics, a -> a:metric = 'tCoachingComplete')[0]:stats:max::number, 0) AS tCoachingComplete_max,
    COALESCE(FILTER(qa.payload:metrics, a -> a:metric = 'tCoachingComplete')[0]:stats:min::number, 0) AS tCoachingComplete_min,
    COALESCE(FILTER(qa.payload:metrics, a -> a:metric = 'tCoachingComplete')[0]:stats:sum::number, 0) AS tCoachingComplete_sum,
    COALESCE(FILTER(qa.payload:metrics, a -> a:metric = 'tConnected')[0]:stats:count::number, 0) AS tConnected_count,
    COALESCE(FILTER(qa.payload:metrics, a -> a:metric = 'tConnected')[0]:stats:max::number, 0) AS tConnected_max,
    COALESCE(FILTER(qa.payload:metrics, a -> a:metric = 'tConnected')[0]:stats:min::number, 0) AS tConnected_min,
