    COALESCE(FILTER(qa.payload:metrics, a -> a:metric = 'tFirstResponse')[0]:stats:max::number, 0) AS tFirstResponse_max,
    COALESCE(FILTER(qa.payload:metrics, a -> a:metric = 'tFirstResponse')[0]:stats:min::number, 0) AS tFirstResponse_min,
