FROM {{ ref("queue_aggregate") }} qa
JOIN {{ ref("queue") }} q ON qa.payload:queueId = q.id
WHERE qa.payload:mediaType = 'voice'
  AND q.payload:name IN ('ACT', 'NSW', 'Victoria', 'QLD', 'SA', 'Other', 'WA', 'Tasmania', 'NT')
{%- if is_incremental() %}
  AND qa.extracted > COALESCE((SELECT MAX(extracted) FROM {{ this }}), '1900-01-01')
{%- endif %}
